import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [data, setData] = useState(null);
  const [selectedStock, setSelectedStock] = useState("RELIANCE.NS");
  const [loading, setLoading] = useState(false);

  const stockList = [
    { name: "Reliance Industries", symbol: "RELIANCE.NS" },
    { name: "TCS", symbol: "TCS.NS" },
    { name: "HDFC Bank", symbol: "HDFCBANK.NS" },
    { name: "Infosys", symbol: "INFY.NS" },
    { name: "Tata Motors", symbol: "TATAMOTORS.NS" },
    { name: "SBI", symbol: "SBIN.NS" }
  ];

  const fetchData = (symbol) => {
    setLoading(true);
    axios.get(`http://localhost:8000/api/analyze?tickers=${symbol}`)
      .then(res => {
        setData(res.data);
        setLoading(false);
      })
      .catch(err => {
        console.error("Backend Error:", err);
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchData(selectedStock);
  }, [selectedStock]);

  if (!data && !loading) return <div style={{color: 'white', textAlign: 'center', marginTop: '50px'}}>Connecting to Backend...</div>;

  return (
    <div style={{ backgroundColor: '#0e1117', color: '#c9d1d9', minHeight: '100vh', padding: '20px', fontFamily: 'monospace' }}>
      
      <div style={{ borderBottom: '1px solid #30363d', paddingBottom: '10px', marginBottom: '20px' }}>
        <h2 style={{ color: '#58a6ff' }}>🛡️ QuantShield AI Portfolio Optimizer</h2>
      </div>

      {/* Stock Selection Dropdown */}
      <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d', marginBottom: '20px' }}>
        <label style={{ marginRight: '15px', fontWeight: 'bold' }}>📁 SELECT ASSET:</label>
        <select 
          value={selectedStock} 
          onChange={(e) => setSelectedStock(e.target.value)}
          style={{ background: '#0d1117', color: 'white', border: '1px solid #58a6ff', padding: '10px', borderRadius: '5px', width: '250px' }}
        >
          {stockList.map(s => <option key={s.symbol} value={s.symbol}>{s.name}</option>)}
        </select>
        {loading && <span style={{marginLeft: '15px', color: '#f1e05a'}}>⚡ Analyzing...</span>}
      </div>

      {data && (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.5fr', gap: '20px' }}>
          
          {/* Left Side: Market Analysis */}
          <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d' }}>
            <h3 style={{ color: '#ff4b4b' }}>📊 Market Analysis</h3>
            <div style={{ lineHeight: '3', fontSize: '18px' }}>
              <div style={{ borderBottom: '1px solid #21262d' }}>Volatility: <b style={{float: 'right', color: '#f85149'}}>{data.volatility || 'Low'}</b></div>
              <div style={{ borderBottom: '1px solid #21262d' }}>Market Regime: <b style={{float: 'right'}}>{data.regime}</b></div>
              <div style={{ borderBottom: '1px solid #21262d' }}>BSI Score: <b style={{float: 'right', color: '#d2a8ff'}}>{data.bsi_score}</b></div>
              <div style={{ borderBottom: '1px solid #21262d' }}>Correlation (CPS): <b style={{float: 'right'}}>{data.cps_score}</b></div>
            </div>

            {/* Ghost Hedge System - Dynamic Status */}
            <div style={{ 
              marginTop: '40px', padding: '20px', textAlign: 'center', borderRadius: '8px',
              background: data.regime === "STRESS" ? '#4a151b' : '#064e3b',
              border: `2px solid ${data.regime === "STRESS" ? '#f85149' : '#238636'}`,
              color: 'white', fontWeight: 'bold'
            }}>
              🛡️ GHOST HEDGE SYSTEM: {data.regime === "STRESS" ? "ACTIVE" : "INACTIVE"}
            </div>
          </div>

          {/* Right Side: Forecast & AI Verdict */}
          <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d' }}>
            <h3 style={{ color: '#58a6ff' }}>🎲 Monte Carlo Risk Forecast</h3>
            
            <div style={{ marginTop: '20px' }}>
              <div style={{ background: '#0d1117', padding: '20px', borderRadius: '10px', marginBottom: '15px', borderLeft: '5px solid #238636' }}>
                <p style={{ margin: 0, color: '#8b949e' }}>Expected Value (on ₹10,000)</p>
                <h1 style={{ color: '#3fb950' }}>₹{data.forecast?.expected}</h1>
              </div>
              <div style={{ background: '#0d1117', padding: '20px', borderRadius: '10px', borderLeft: '5px solid #f85149' }}>
                <p style={{ margin: 0, color: '#8b949e' }}>Worst Case Scenario</p>
                <h1 style={{ color: '#f85149' }}>₹{data.forecast?.worst_case}</h1>
              </div>
            </div>

            {/* AI VERDICT - BUY / HOLD / AVOID */}
            <div style={{ 
              marginTop: '30px', padding: '25px', textAlign: 'center', borderRadius: '10px', 
              background: data.decision === "BUY" ? '#238636' : data.decision === "AVOID" ? '#f85149' : '#f1e05a',
              color: data.decision === "HOLD" ? 'black' : 'white',
              fontSize: '28px', fontWeight: 'extrabold', letterSpacing: '2px'
            }}>
              🤖 AI VERDICT: {data.decision}
            </div>
          </div>

        </div>
      )}
    </div>
  );
}

export default App;
